-- Mountain Social Adventure v2.0 TRAVERSAL HOTFIX
local Workspace=game:GetService("Workspace");local Lighting=game:GetService("Lighting");local Terrain=Workspace.Terrain
local ROOT_NAME="ACC_MountainSocial";local old=Workspace:FindFirstChild(ROOT_NAME);if old then old:Destroy()end
local root=Instance.new("Folder");root.Name=ROOT_NAME;root.Parent=Workspace
local folders={};for _,n in ipairs({"Checkpoints","Camps","PhotoSpots","Secrets","Decor","RouteAnchors"})do local f=Instance.new("Folder");f.Name=n;f.Parent=root;folders[n]=f end
local function part(n,s,cf,m,c,p,tr,coll)local x=Instance.new("Part");x.Name=n;x.Anchored=true;x.Size=s;x.CFrame=cf;x.Material=m or Enum.Material.Slate;if c then x.Color=c end;x.Transparency=tr or 0;x.CanCollide=coll~=false;x.TopSurface=Enum.SurfaceType.Smooth;x.BottomSurface=Enum.SurfaceType.Smooth;x.Parent=p or root;return x end
local function anchor(n,pos,p)local x=part(n,Vector3.new(10,1,10),CFrame.new(pos),Enum.Material.SmoothPlastic,Color3.fromRGB(244,186,72),p,.94,false);x:SetAttribute("ACCAnchor",true);return x end
local function trail(n,a,b,w)local d=b-a;local dist=d.Magnitude;local mid=(a+b)/2;local x=part(n,Vector3.new(w,2.2,dist),CFrame.lookAt(mid,b),Enum.Material.Ground,Color3.fromRGB(100,84,64),root,.02,true);x:SetAttribute("RouteSegment",true);return x end
