-- Wide, solid, walkable route. Earlier route parts had CanCollide=false and players fell through.
for i=1,#route-1 do local a,b=route[i][2],route[i+1][2];local dir=b-a;local side=Vector3.new(-dir.Z,0,dir.X);if side.Magnitude>0 then side=side.Unit end;local pts={a};for s=1,3 do local t=s/4;local base=a:Lerp(b,t);local sway=math.sin((i*1.7+s)*1.2)*(10+(i%3)*3);table.insert(pts,base+side*sway)end;table.insert(pts,b);for j=1,#pts-1 do trail(string.format("Trail_%02d_%02d",i,j),pts[j]-Vector3.new(0,1.5,0),pts[j+1]-Vector3.new(0,1.5,0),i<5 and 18 or 14)end end
-- Solid safety clearings under every checkpoint.
for i,info in ipairs(route)do local pos=info[2];local pad=part("TrailSafePad_"..i,Vector3.new(i==1 and 42 or 24,2,i==1 and 42 or 24),CFrame.new(pos-Vector3.new(0,1.6,0)),i<7 and Enum.Material.Ground or Enum.Material.Rock,i<7 and Color3.fromRGB(96,84,66) or Color3.fromRGB(90,91,89),root,0,true);local cp=anchor(string.format("CP%02d_%s",i,info[1]:gsub(" ","_")),pos+Vector3.new(0,1.5,0),folders.Checkpoints);cp:SetAttribute("CheckpointIndex",i);cp:SetAttribute("CheckpointName",info[1]);cp:SetAttribute("SaveReady",true)end
