for _,idx in ipairs({1,5,9})do local pos=route[idx][2];local camp=Instance.new("Model");camp.Name="Camp_"..idx;camp.Parent=folders.Camps;local fire=part("Campfire",Vector3.new(4,1,4),CFrame.new(pos+Vector3.new(15,1,8)),Enum.Material.Slate,Color3.fromRGB(72,70,66),camp,0,true);fire:SetAttribute("CampfireReady",true);local l=Instance.new("PointLight");l.Range=20;l.Brightness=1.7;l.Color=Color3.fromRGB(255,178,96);l.Parent=fire end
